@php($money = fn($n) => 'Bs '.number_format($n / 100, 2, '.', ',')) @if($summary)<div class="alert">Este resumen incluye ?nicamente pedidos vinculados a este turno. Las ventas de APK que no env?an caja no aparecen aqu?; conc?lialas por separado antes del cierre.</div>@if($shift->closed_at)<p class="muted">Los importes reflejan la instant?nea del cierre; el estado actual de un pedido puede haber cambiado despu?s.</p>@endif<div class="grid">@foreach(['Fondo inicial'=>$shift->opening_cents,'Ventas en efectivo'=>$summary['cash_sales_cents'],'Entradas de efectivo'=>$summary['cash_inflows_cents'] ?? 0,'Salidas de efectivo'=>$summary['cash_outflows_cents'] ?? 0,'Efectivo esperado'=>$shift->closed_at ? $shift->expected_cents : $shift->opening_cents + $summary['cash_sales_cents'] + ($summary['cash_inflows_cents'] ?? 0) - ($summary['cash_outflows_cents'] ?? 0),'Transferencias independientes'=>$summary['bank_independent_cents'] ?? 0,'Excedente de transferencia vinculada'=>$summary['bank_linked_change_cents'] ?? 0,'Bancos verificados'=>$summary['bank_verified_cents'] ?? $summary['methods_cents']['QR_STATIC_VERIFIED'],'QR simulado'=>$summary['methods_cents']['QR_SIMULATED'],'QR est?tico verificado'=>$summary['methods_cents']['QR_STATIC_VERIFIED'],'QR pendiente'=>$summary['methods_cents']['QR_STATIC_PENDING'],'Pedidos sin pagar'=>$summary['methods_cents']['UNPAID'],'Total vendido'=>$summary['total_cents']] as $label=>$value)<div class="card"><span>{{ $label }}</span><strong>{{ $money($value) }}</strong></div>@endforeach</div><div class="panel"><h2>Desglose por vendedor</h2><div class="table"><table><thead><tr><th>Responsable</th><th>Pedidos</th><th>Total</th></tr></thead><tbody>@forelse($summary['workers'] as $worker)<tr><td>{{ $worker['name'] ?? 'Usuario #'.$worker['seller_id'] }}</td><td>{{ $worker['order_count'] }}</td><td>{{ $money($worker['total_cents']) }}</td></tr>@empty<tr><td colspan="3">Sin pedidos en este turno.</td></tr>@endforelse</tbody></table></div></div>@else<div class="alert">Este cierre hist?rico no dispone de instant?nea de resumen.</div>@endif